program.compute:
options = read('/input/options')
gamma = [o for o in options if 'gamma' in o['tags']]
result = []
for o in gamma:
    candidate = [o['id']] + o['requires']
    if len(candidate) >= goal['min_count'] and len(candidate) <= goal['max_count'] and valid(candidate):
        result = candidate
        break
if result == []:
    for o in gamma:
        for p in options:
            for q in options:
                candidate = [o['id'], p['id'], q['id']]
                if len(candidate) >= goal['min_count'] and len(candidate) <= goal['max_count'] and valid(candidate):
                    result = candidate
                    break
            if result != []:
                break
        if result != []:
            break

program.effects:
if exists('/output/selection'):
    existing = read('/output/selection')
    if valid(existing):
        result = existing
    else:
        result = []
if result != [] and valid(result):
    if not exists('/output/selection'):
        write('/output/selection', result)
    if status('report') == 'not_sent':
        send('report', 'team', result)
    if exists('/tmp/cache'):
        delete('/tmp/cache')

